import pytest

class HL7ParserError(Exception):
    pass

class HL7MissingSegmentError(HL7ParserError):
    pass

class HL7ValidationError(HL7ParserError):
    pass

class InvalidLoincError(HL7ValidationError):
    pass


@pytest.fixture
def base_msh():
    return "MSH|^~\\&|EPIC|HOSPITAL|LAB_LIS|CENTRAL_LAB|20240515103000||ORU^R01|MSG20240515001|P|2.5.1"


def build_msh(message_type="ORU^R01", control_id="MSG20240515001", version="2.5.1"):
    return f"MSH|^~\\&|EPIC|HOSPITAL|LAB_LIS|CENTRAL_LAB|20240515103000||{message_type}|{control_id}|P|{version}"


class TestMSHSegmentValidation:
    @pytest.mark.parametrize("bad_msh_9", ["ADT^A01", "ORU", "^R01", ""])
    def test_rejects_invalid_message_type(self, bad_msh_9, hl7_lab_result_parser):
        msh = build_msh(message_type=bad_msh_9)
        payload = f"{msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|2951-2^Na^LN||138\r"
        with pytest.raises(HL7ValidationError):
            hl7_lab_result_parser.parse(payload)

    @pytest.mark.parametrize("empty_control_id", ["", "   "])
    def test_rejects_blank_control_id(self, empty_control_id, hl7_lab_result_parser):
        msh = build_msh(control_id=empty_control_id)
        payload = f"{msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|2951-2^Na^LN||138\r"
        with pytest.raises(HL7ValidationError):
            hl7_lab_result_parser.parse(payload)

    def test_rejects_missing_msh_header(self, hl7_lab_result_parser):
        payload = "PID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|2951-2^Na^LN||138\r"
        with pytest.raises(HL7MissingSegmentError):
            hl7_lab_result_parser.parse(payload)


class TestOBRSegmentParsing:
    def test_parses_order_identifiers(self, base_msh, hl7_lab_result_parser):
        payload = f"{base_msh}\rPID|1||MRN123||DOE^J\rOBR|1|ORD999|LAB888|2951-2^Sodium^LN|||20240515090000\rOBX|1|NM|2951-2^Sodium^LN||138\r"
        parsed = hl7_lab_result_parser.parse(payload)
        obr = parsed.orders[0]
        assert obr.placer_order_number == "ORD999"
        assert obr.filler_order_number == "LAB888"


class TestOBXSegmentParsing:
    @pytest.mark.parametrize("valid_flag", ["L", "H", "LL", "HH", "A", "", None])
    def test_accepts_table_0078_abnormal_flags(self, valid_flag, base_msh, hl7_lab_result_parser):
        flag_str = valid_flag if valid_flag is not None else ""
        payload = f"{base_msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|2951-2^Na^LN||138|mmol/L|135-145|{flag_str}|||F\r"
        parsed = hl7_lab_result_parser.parse(payload)
        assert parsed.orders[0].observations[0].abnormal_flag == valid_flag

    @pytest.mark.parametrize("invalid_flag", ["low", "high", "Normal", "CRIT"])
    def test_rejects_non_table_0078_flags(self, invalid_flag, base_msh, hl7_lab_result_parser):
        payload = f"{base_msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|2951-2^Na^LN||138|mmol/L|135-145|{invalid_flag}|||F\r"
        with pytest.raises(HL7ValidationError):
            hl7_lab_result_parser.parse(payload)

    @pytest.mark.parametrize("invalid_loinc", ["29512", "2951-X", "INVALID", "12-3", ""])
    def test_rejects_malformed_loinc(self, invalid_loinc, base_msh, hl7_lab_result_parser):
        payload = f"{base_msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|2951-2^Na^LN\rOBX|1|NM|{invalid_loinc}^Na^LN||138\r"
        with pytest.raises(InvalidLoincError):
            hl7_lab_result_parser.parse(payload)

    def test_repeating_observation_values(self, base_msh, hl7_lab_result_parser):
        payload = f"{base_msh}\rPID|1||MRN123||DOE^J\rOBR|1|O1|L1|6463-4^Culture^LN\rOBX|1|ST|6463-4^Culture^LN||E. coli~E. faecalis||||||F\r"
        parsed = hl7_lab_result_parser.parse(payload)
        assert parsed.orders[0].observations[0].value == ["E. coli", "E. faecalis"]


class TestNTESegmentBinding:
    def test_binds_notes_to_preceding_segments(self, base_msh, hl7_lab_result_parser):
        payload = "\r".join([
            base_msh,
            "PID|1||MRN123||DOE^J",
            "OBR|1|O1|L1|2951-2^Na^LN",
            "NTE|1|L|OBR Level Note",
            "OBX|1|NM|2951-2^Na^LN||138",
            "NTE|1|L|OBX Level Note",
        ]) + "\r"
        parsed = hl7_lab_result_parser.parse(payload)
        assert parsed.orders[0].notes[0].comment == "OBR Level Note"
        assert parsed.orders[0].observations[0].notes[0].comment == "OBX Level Note"
