def compute_sig(timestamp: int, payload: bytes, secret: str = PRIMARY_LIVE) -> str:
    """Helper defaults to current module PRIMARY_LIVE secret unless explicitly passed."""
    signed_payload = f"{timestamp}.".encode("utf-8") + payload
    return hmac.new(
        secret.encode("utf-8"),
