Here is the restructured test suite adhering to the specified ordering, helper fixture, parametrization, and naming style:

```python
import struct
import pytest
from decimal import Decimal
from apextrack.decoder import (
    tg4x_decode_payload,
    ProbeStatus,
    ProbeReading,
    ChecksumError,
    FrameFormatError,
)


def _compute_crc16(data: bytes) -> int:
    crc = 0xFFFF
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = (crc << 1) ^ 0x1021
            else:
                crc <<= 1
            crc &= 0xFFFF
    return crc


@pytest.fixture
def make_tg4x_frame():
    def _factory(payload_hex: str, crc: int | None = None) -> bytes:
        body = bytes.fromhex(payload_hex)
        frame_crc = _compute_crc16(body) if crc is None else crc
        return body + struct.pack(">H", frame_crc)
    return _factory


# 1. Rejection and corruption tests

def test_tg4x_decode_bad_sync_bytes(make_tg4x_frame):
    # Replaces default sync 0xAA55 with 0xBB66
    frame = make_tg4x_frame("BB66015F0866")
    with pytest.raises(FrameFormatError, match="Invalid sync sequence"):
        tg4x_decode_payload(frame)


def test_tg4x_decode_truncated_payload():
    with pytest.raises(FrameFormatError, match="Payload shorter than minimum length"):
        tg4x_decode_payload(b"\xaa\x55\x01")


def test_tg4x_decode_corrupted_crc(make_tg4x_frame):
    corrupted_frame = make_tg4x_frame("AA55015F0866", crc=0xDEAD)
    with pytest.raises(ChecksumError, match="CRC16 validation failed"):
        tg4x_decode_payload(corrupted_frame)


# 2. Parametrized probe sentinel, fault, and boundary tests

@pytest.mark.parametrize(
    "probe_hex, expected_status, expected_temp",
    [
        ("7FFF", ProbeStatus.FAULT, None),
        ("7FFE", ProbeStatus.OUT_OF_BOUNDS, None),
        ("F060", ProbeStatus.OK, Decimal("-40.00")),
        ("2134", ProbeStatus.OK, Decimal("85.00")),
        ("0000", ProbeStatus.OK, Decimal("0.00")),
    ],
)
def test_tg4x_decode_probe_status_and_boundaries(
    make_tg4x_frame, probe_hex, expected_status, expected_temp
):
    # Header: AA55 (sync) + 01 (msg_type) + 5F (95% battery)
    body_hex = f"AA55015F{probe_hex}"
    frame = make_tg4x_frame(body_hex)

    result = tg4x_decode_payload(frame)

    assert result.probe == ProbeReading(status=expected_status, temp_c=expected_temp)
```

