"""Unit and regression tests for validate_delivery_policy in services.webhook_dispatcher."""

import pytest
from services.webhook_dispatcher import (
    validate_delivery_policy,
    DeliveryPolicy,
    PolicyValidationError,
)


class TestValidateDeliveryPolicySuccess:
    """Tests validating legitimate configurations, defaults, and boundary conditions."""

    def test_minimal_valid_payload_uses_defaults(self):
        raw = {
            "policy_id": "pol-a9c2x1",
            "target_url": "https://hooks.external-partner.com/v1/events",
        }
        policy = validate_delivery_policy(raw)
        assert isinstance(policy, DeliveryPolicy)
        assert policy.policy_id == "pol-a9c2x1"
        assert policy.target_url == "https://hooks.external-partner.com/v1/events"
        assert policy.max_retries == 3
        assert policy.timeout_ms == 3000

    @pytest.mark.parametrize(
        "max_retries,timeout_ms",
        [
            (0, 100),       # lowest boundaries
            (5, 10000),     # highest boundaries
            (2, 4500),      # mid values
        ],
    )
    def test_explicit_boundary_and_override_values(self, max_retries, timeout_ms):
        raw = {
            "policy_id": "pol-123456",
            "target_url": "https://api.example.com/webhook",
            "max_retries": max_retries,
            "timeout_ms": timeout_ms,
        }
        policy = validate_delivery_policy(raw)
        assert policy.max_retries == max_retries
        assert policy.timeout_ms == timeout_ms


class TestValidateDeliveryPolicyFailures:
    """Tests asserting validation failures and specific PolicyValidationError codes."""

    @pytest.mark.parametrize(
        "bad_id",
        [
            None,
            "",
            "pol-ABC123",       # uppercase not allowed
            "pol-12345",        # too short (5 chars)
            "pol-1234567",      # too long (7 chars)
            "sub-123456",       # wrong prefix
            123456,             # non-string
        ],
    )
    def test_invalid_policy_id(self, bad_id):
        raw = {
            "policy_id": bad_id,
            "target_url": "https://api.example.com/webhook",
        }
        with pytest.raises(PolicyValidationError) as exc_info:
            validate_delivery_policy(raw)
        assert exc_info.value.code == "ERR_INVALID_ID"

    def test_missing_policy_id(self):
        raw = {"target_url": "https://api.example.com/webhook"}
        with pytest.raises(PolicyValidationError) as exc_info:
            validate_delivery_policy(raw)
        assert exc_info.value.code == "ERR_INVALID_ID"

    def test_insecure_http_url(self):
        raw = {
            "policy_id": "pol-000001",
            "target_url": "http://api.example.com/webhook",
        }
        with pytest.raises(PolicyValidationError) as exc_info:
            validate_delivery_policy(raw)
        assert exc_info.value.code == "ERR_INSECURE_URL"

    @pytest.mark.parametrize(
        "malformed_url",
        [
            "",
            "not-a-url",
            "ftp://api.example.com/resource",
            "https://",
            None,
        ],
    )
    def test_malformed_url(self, malformed_url):
        raw = {
            "policy_id": "pol-000001",
            "target_url": malformed_url,
        }
        with pytest.raises(PolicyValidationError) as exc_info:
            validate_delivery_policy(raw)
        assert exc_info.value.code == "ERR_MALFORMED_URL"

    @pytest.mark.parametrize("bad_retries", [-1, 6, 10, "3", 3.5, None])
