        raw = {
            "policy_id": "pol-000001",
            "target_url": "https://api.example.com/webhook",
            "max_retries": bad_retries,
        }
        with pytest.raises(PolicyValidationError) as exc_info:
            validate_delivery_policy(raw)
        assert exc_info.value.code == "ERR_INVALID_RETRIES"

    @pytest.mark.parametrize("bad_timeout", [99, 10001, 0, -500, "3000", 500.5, None])
