Here is a complete `pytest` test suite covering the parsing rules, field constraints, validation errors, and ABA routing transit checksum logic for `AchNocRuleEngine`.

```python
import pytest
from typing import NamedTuple

# Reference imports (or adjust paths to match your project structure):
# from banking.ach.noc import AchNocRuleEngine, InvalidNocCodeError, NocValidationError


def calculate_aba_checksum(routing_number: str) -> bool:
    """Standard Fedwire/ACH routing transit 3-7-1 weighting algorithm."""
    if not routing_number.isdigit() or len(routing_number) != 9:
        return False
    weights = [3, 7, 1, 3, 7, 1, 3, 7, 1]
    total = sum(int(digit) * weight for digit, weight in zip(routing_number, weights))
    return total % 10 == 0


class TestAchNocRuleEngineValidCodes:
    @pytest.mark.parametrize(
        "code, payload, expected_field, expected_val",
        [
            ("C01", {"corrected_data": "011000015"}, "new_routing_number", "011000015"),
            ("C02", {"corrected_data": "9876543210123456"}, "new_account_number", "9876543210123456"),
            ("C03", {"corrected_data": "011000015987654321"}, "has_composite_update", True),
        ],
    )
    def test_parse_supported_noc_codes(code, payload, expected_field, expected_val):
        engine = AchNocRuleEngine()
        result = engine.parse(code=code, data=payload)

        assert result.code == code
        assert getattr(result, expected_field) == expected_val
        assert result.is_valid is True


class TestAchNocC01TransitRoutingRules:
    @pytest.mark.parametrize(
        "valid_routing",
        [
            "011000015",  # Federal Reserve Bank of Boston
            "121000358",  # Wells Fargo Bank, N.A.
            "021000021",  # JPMorgan Chase Bank, N.A.
        ],
    )
    def test_c01_valid_9_digit_routing_and_checksum(valid_routing):
        engine = AchNocRuleEngine()
        result = engine.parse(code="C01", data={"corrected_data": valid_routing})
        assert result.new_routing_number == valid_routing

    @pytest.mark.parametrize(
        "malformed_routing",
        [
            "11000015",     # 8 digits
            "0110000150",   # 10 digits
            "01100001A",    # Non-numeric
            "",             # Empty string
        ],
    )
    def test_c01_rejects_non_9_digit_routing(malformed_routing):
        engine = AchNocRuleEngine()
        with pytest.raises(NocValidationError, match=r"(?i)routing.*9 digits"):
            engine.parse(code="C01", data={"corrected_data": malformed_routing})

    @pytest.mark.parametrize(
        "invalid_checksum_routing",
        [
            "011000016",  # Off-by-one check digit
            "123456789",  # Standard invalid ABA
            "111111111",  # Bad checksum
        ],
    )
    def test_c01_rejects_invalid_aba_checksum(invalid_checksum_routing):
