Here is the consolidated test suite reorganized so that all validation and error categories appear first, followed by payload parsing and alarm flag evaluations.

```python
import functools
import operator
import struct
import pytest

# Adjust imports to your package layout:
# from pharma_iot.decoders import (
#     TempGuardDecoder,
#     CorruptFrameError,
#     InvalidSensorDataError,
#     TimestampRangeError,
#     CrcMismatchError,
# )

MIN_VALID_TIMESTAMP = 1577836800  # 2020-01-01T00:00:00Z


def compute_xor_crc(data: bytes) -> int:
    return functools.reduce(operator.xor, data, 0)


def build_tg8_packet(
    sync=0xAA55,
    device_id=501,
    timestamp=1710508800,
    temp_raw=450,
    battery=80,
    status_flags=0,
    override_crc=None,
) -> str:
    payload_body = struct.pack(">HHIhBB", sync, device_id, timestamp, temp_raw, battery, status_flags)
    crc = compute_xor_crc(payload_body) if override_crc is None else override_crc
    return (payload_body + struct.pack("B", crc)).hex()


# =====================================================================
# 1. ERROR CATEGORIES
# =====================================================================

class TestCorruptFrameAndLengthErrors:
    @pytest.fixture
    def decoder(self):
        return TempGuardDecoder()

    def test_reject_empty_string(self, decoder):
        with pytest.raises(CorruptFrameError):
            decoder.decode("")

    @pytest.mark.parametrize("length", [1, 5, 10, 11, 12])
    def test_reject_truncated_lengths(self, decoder, length):
        payload = (b"\xAA\x55" + b"\x00" * (length - 2)) if length >= 2 else b"\xAA"[:length]
        with pytest.raises(CorruptFrameError, match="(?i)length"):
            decoder.decode(payload.hex())

    @pytest.mark.parametrize("invalid_sync", [0xAA54, 0x0000, 0xFFFF, 0x55AA])
    def test_reject_invalid_sync_header(self, decoder, invalid_sync):
        bad_hex = build_tg8_packet(sync=invalid_sync)
        with pytest.raises(CorruptFrameError, match="(?i)sync|header"):
            decoder.decode(bad_hex)


class TestCrcValidationErrors:
    @pytest.fixture
    def decoder(self):
        return TempGuardDecoder()

    @pytest.mark.parametrize("bad_crc", [0x00, 0xA5, 0xFF])
    def test_reject_mismatched_crc(self, decoder, bad_crc):
        packet = build_tg8_packet(override_crc=bad_crc)
        with pytest.raises(CrcMismatchError, match="(?i)crc"):
            decoder.decode(packet)


class TestFieldValidationErrors:
    @pytest.fixture
    def decoder(self):
        return TempGuardDecoder()

    @pytest.mark.parametrize("invalid_ts", [0, 100000, 1577836800])
    def test_reject_timestamp_on_or_before_boundary(self, decoder, invalid_ts):
        bad_ts_hex = build_tg8_packet(timestamp=invalid_ts)
        with pytest.raises(TimestampRangeError, match="(?i)timestamp"):
            decoder.decode(bad_ts_hex)

    @pytest.mark.parametrize("bad_battery", [101, 110, 255])
    def test_reject_battery_over_100_percent(self, decoder, bad_battery):
        bad_batt_hex = build_tg8_packet(battery=bad_battery)
        with pytest.raises(InvalidSensorDataError, match="(?i)battery"):
            decoder.decode(bad_batt_hex)


# =====================================================================
# 2. HAPPY PATH & PAYLOAD PARSING
# =====================================================================

class TestValidPayloadParsing:
    @pytest.fixture
    def decoder(self):
        return TempGuardDecoder()

    def test_parse_valid_baseline_packet(self, decoder):
        raw_hex = build_tg8_packet(device_id=1001, timestamp=1710508801, temp_raw=2250, battery=100)
        result = decoder.decode(raw_hex)
        assert result.device_id == 1001
        assert result.timestamp == 1710508801
        assert result.temperature_celsius == pytest.approx(22.50, abs=1e-2)
        assert result.battery_percent == 100

    @pytest.mark.parametrize(
        "raw_temp, expected_celsius",
        [
            (-4000, -40.00),
            (-2000, -20.00),
            (-525, -5.25),
            (0, 0.00),
            (2500, 25.00),
        ],
    )
    def test_temperature_scaling_across_ranges(self, decoder, raw_temp, expected_celsius):
        raw_hex = build_tg8_packet(temp_raw=raw_temp)
        result = decoder.decode(raw_hex)
        assert result.temperature_celsius == pytest.approx(expected_celsius, abs=1e-2)

    @pytest.mark.parametrize(
        "flags, exp_high, exp_low, exp_probe_fault",
        [
            (0b00000000, False, False, False),
            (0b00000001, True, False, False),
            (0b00000010, False, True, False),
            (0b00000100, False, False, True),
            (0b00000111, True, True, True),
        ],
    )
    def test_status_alarm_flags(self, decoder, flags, exp_high, exp_low, exp_probe_fault):
        raw_hex = build_tg8_packet(status_flags=flags)
        result = decoder.decode(raw_hex)
        assert result.high_temp_alarm is exp_high
        assert result.low_temp_alarm is exp_low
        assert result.probe_fault is exp_probe_fault
```

