  name        = "SEC-8821-erostova-assume-billing-audit"
  description = "SEC-8821: Allow erostova temporary assume access to BillingAuditInvestigatorRole per CISO approval"
  path        = "/security/audits/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAssumeBillingAuditRole"
        Effect = "Allow"
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Resource = "arn:aws:iam::112233445566:role/BillingAuditInvestigatorRole"
